/* Quiz data (QZ: lesson → MCQs) and recall prompts (RC: lesson → prompts per review day).
   Part of the course scripts. Every page loads, in this order: course-index.js, quiz-data.js, course.js, effects.js,
   then the labs of each course and run-java.js. They are classic scripts, so
   top-level const/let/function names are shared between them (course.js defines $, $$, esc, store, hl, FX, THM…). */
"use strict";
/* learning layer: quiz data (QZ: lesson → MCQs {lv,q,o,a,e}; RC: lesson → recall prompts per review day).
   Java quizzes come back lesson by lesson as the course is rebuilt (QZ.l01, RC.l01, …); the v1 set is in archive/java-v1. */
const QZ={},RC={};
/* @quiz-data */

/* SQL 00 (foundations) quiz and recall prompts. Every result was produced by the course database (assets/data/sql-seed.js) in SQLite 3.49. */
QZ.s00=[
{lv:"B",q:"Which clause decides <b>which table</b> a query reads?",o:["<code>SELECT</code>","<code>FROM</code>","<code>WHERE</code>","<code>ORDER BY</code>"],a:1,e:"<code>FROM</code> names the drawer; <code>SELECT</code> only picks the labels (columns) to read from it."},
{lv:"B",q:"What does <code>SELECT 7 / 2;</code> return in SQLite and PostgreSQL?",o:["3.5","3","4","an error"],a:1,e:"Two integers divide as integers, exactly like Java: 3. Write <code>7 / 2.0</code> for 3.5. (MySQL is the odd one out: it returns 3.5000.)"},
{lv:"B",q:"How many rows does <code>SELECT name FROM customers WHERE city = NULL;</code> return? (Customer 10 has a NULL city.)",o:["1","0","10","an error"],a:1,e:"None. <code>= NULL</code> is never true because comparing with an unknown value is unknown, and WHERE keeps only true. <code>WHERE city IS NULL</code> returns Rahul."},
{lv:"B",q:"<code>services</code> has 8 rows and two of them have a NULL <code>cost</code>. What do <code>COUNT(*)</code> and <code>COUNT(cost)</code> return?",o:["8 and 8","8 and 6","6 and 6","8 and 2"],a:1,e:"<code>COUNT(*)</code> counts rows (8); <code>COUNT(cost)</code> counts non-NULL costs (6)."},
{lv:"B",q:"Which of these is the <b>primary key</b> of <code>sales</code>?",o:["<code>car_id</code>","<code>customer_id</code>","<code>id</code>","<code>sold_on</code>"],a:2,e:"<code>id</code> identifies the sale. <code>car_id</code>, <code>customer_id</code> and <code>employee_id</code> are foreign keys pointing at other tables' primary keys."},
{lv:"I",q:"Which clause runs <b>first</b> when the engine executes a query?",o:["<code>SELECT</code>","<code>WHERE</code>","<code>FROM</code>","<code>ORDER BY</code>"],a:2,e:"FROM → WHERE → GROUP BY → HAVING → SELECT → ORDER BY → LIMIT. SELECT is written first and executed fifth."},
{lv:"I",q:"Why does this fail?<pre><code>SELECT brand, COUNT(*) AS models\nFROM cars\nWHERE models &gt;= 2\nGROUP BY brand;</code></pre>",o:["<code>COUNT</code> needs <code>DISTINCT</code>","<code>WHERE</code> runs before <code>SELECT</code>, so the alias <code>models</code> does not exist yet","<code>GROUP BY</code> must come before <code>WHERE</code>","Aliases need double quotes"],a:1,e:"WHERE runs before GROUP BY and SELECT: nothing is counted and no alias exists. Use <code>HAVING COUNT(*) &gt;= 2</code> after GROUP BY."},
{lv:"I",q:"<code>WHERE</code> vs <code>HAVING</code>: which statement is correct?",o:["They are interchangeable","<code>WHERE</code> filters rows before grouping; <code>HAVING</code> filters groups after it","<code>HAVING</code> is faster","<code>WHERE</code> can use aggregates, <code>HAVING</code> cannot"],a:1,e:"WHERE sees individual rows and cannot use aggregates; HAVING sees groups and can. Prefer WHERE when no aggregate is needed: it removes rows earlier."},
{lv:"I",q:"<code>SELECT name FROM customers ORDER BY joined_on LIMIT 3 OFFSET 2;</code> returns which names?",o:["Asha, Ravi, Meera","Meera, Kiran, Divya","Ravi, Meera, Kiran","Kiran, Divya, Arjun"],a:1,e:"Sorted by join date the list is Asha, Ravi, Meera, Kiran, Divya…; OFFSET 2 skips the first two and LIMIT 3 takes the next three."},
{lv:"A",q:"What happens?<pre><code>INSERT INTO cars VALUES (1, 'Maruti', 'Dzire', 2024, 700000, 'white', 1);</code></pre>(car 1 already exists)",o:["The old row is replaced","A second row with id 1 is added","The statement is refused: UNIQUE constraint failed on <code>cars.id</code>","Only the model name is updated"],a:2,e:"A primary key must be unique. The whole statement is rejected and nothing changes. (Upserts that replace are Lesson S09.)"},
{lv:"A",q:"With foreign keys enforced, what does <code>INSERT INTO sales VALUES (16, 99, 1, 4, '2024-09-01', 100);</code> do? (There is no car 99.)",o:["Inserts the sale with a dangling reference","Creates car 99 automatically","Is refused: FOREIGN KEY constraint failed","Inserts it with car_id set to NULL"],a:2,e:"A foreign key must point at an existing row. SQLite enforces this only after <code>PRAGMA foreign_keys = ON</code>; PostgreSQL and MySQL/InnoDB always do."},
{lv:"A",q:"A query without <code>ORDER BY</code> returned rows in id order yesterday. Is that guaranteed tomorrow?",o:["Yes, tables keep insertion order","Yes, if the table has a primary key","No: without ORDER BY the order is whatever the plan produced, and it can change","Only in PostgreSQL"],a:2,e:"Row order is undefined without ORDER BY. A new index, more data or a different plan can change it. Always sort explicitly, by something unique for pagination."}];
RC.s00={d1:[["Table, row, column, primary key: the four cabinet words?","Drawer, folder, label, folder number."],["The logical order of a query?","FROM, WHERE, GROUP BY, HAVING, SELECT, ORDER BY, LIMIT."],["How do you test for a missing value?","IS NULL, never = NULL."]],
 d3:[["Why can ORDER BY use a SELECT alias but WHERE cannot?","ORDER BY runs after SELECT; WHERE runs before it."],["COUNT(*) vs COUNT(col)?","Rows vs non-NULL values of col."],["What is a foreign key, in one sentence?","A column holding another row's primary key, enforced by the database."]],
 d7:[["WHERE vs HAVING?","Rows before grouping vs groups after; only HAVING can use aggregates."],["What does the database do with a statement that violates a key?","Refuses the whole statement; nothing is half-written."],["Is row order without ORDER BY guaranteed?","No. Only ORDER BY guarantees it."]]};

/* Lesson 01 (What is a String? where it lives, the String Constant Pool). Every output was checked on JDK 25. */
QZ.l00=[
{lv:"B",q:`What does <code>javac Hello.java</code> produce?`,
 o:[`A program that runs only on this computer`,`<code>Hello.class</code>: bytecode that any JVM can run`,`A JVM`,`The output of the program`],
 a:1,e:`The compiler turns source text into <b>bytecode</b>, a <code>.class</code> file that is the same on every operating system. Running it is the job of the <code>java</code> command, which starts a JVM.`},
{lv:"B",q:`Which one do you install to write Java programs?`,
 o:[`The JVM`,`The JRE`,`The JDK`,`Bytecode`],
 a:2,e:`Only the <b>JDK</b> has <code>javac</code> and the other tools. It contains the JRE (the class library) and the JVM, so one install gives you all three.`},
{lv:"B",q:`How many primitive types does Java have?`,
 o:[`4`,`6`,`8`,`As many as you declare`],
 a:2,e:`Eight: <code>byte short int long float double char boolean</code>. Everything else, including <code>String</code> and arrays, is a reference type.`},
{lv:"B",q:`<code>int a = 10; int b = a; b = b + 1;</code> What is <code>a</code> now?`,
 o:[`10`,`11`,`0`,`It depends on the JVM`],
 a:0,e:`A primitive variable holds the value itself, so <code>b = a</code> copied the number 10 into <code>b</code>. Changing <code>b</code> afterwards cannot touch <code>a</code>.`},
{lv:"I",q:`<code>int[] x = {1, 2, 3}; int[] y = x; y[0] = 99;</code> What is <code>x[0]</code>?`,
 o:[`1`,`99`,`0`,`Compile error`],
 a:1,e:`An array is an object, so <code>x</code> and <code>y</code> are <b>references</b>. <code>y = x</code> copied the address: both names point at the same array, and the change is visible through either.`},
{lv:"I",q:`Which line does <b>not</b> compile?`,
 o:[`<code>String s = null;</code>`,`<code>int[] a = null;</code>`,`<code>int n = null;</code>`,`<code>Integer n = null;</code>`],
 a:2,e:`<code>null</code> means "no object", so only reference variables can hold it. <code>int</code> is a primitive and always holds a number; <code>Integer</code> is the wrapper class, a reference, so it may be null.`},
{lv:"I",q:`<code>System.out.println(7 / 2);</code> prints…`,
 o:[`3.5`,`3`,`4`,`3.0`],
 a:1,e:`Both operands are <code>int</code>, so the division is integer division and the fraction is dropped. Write <code>7 / 2.0</code> to get 3.5.`},
{lv:"I",q:`Where does the JVM keep a method's local variables, the objects they point at, and the loaded classes?`,
 o:[`All on the heap`,`Stack, heap, Metaspace`,`Heap, stack, Metaspace`,`Metaspace, heap, stack`],
 a:1,e:`Local variables live in a <b>stack</b> frame, objects on the <b>heap</b>, and each loaded class in <b>Metaspace</b>. Lesson 01 uses this picture for Strings.`}
];
RC.l00={
 d1:[[`What are JDK, JRE and JVM?`,`JVM runs bytecode; JRE = JVM + the class library; JDK = JRE + tools such as <code>javac</code>. Install the JDK.`],
     [`Name the eight primitive types.`,`<code>byte short int long float double char boolean</code>. Everything else is a reference type.`]],
 d3:[[`Why does the same <code>.class</code> file run on Windows and Linux?`,`It is bytecode, not machine code. Each OS has its own JVM that reads the same bytecode.`],
     [`What happens when you copy a primitive variable, and when you copy a reference variable?`,`Primitive: the value is copied; the two variables are independent. Reference: the address is copied; both variables point at the same object.`]],
 d7:[[`Explain stack, heap and Metaspace to a friend in three sentences.`,`The stack holds each running method's variables and is cleared when the method returns. The heap holds every object until the garbage collector finds nothing pointing at it. Metaspace holds the loaded classes.`],
     [`Why can an <code>int</code> never be null, but an <code>Integer</code> can?`,`<code>int</code> is a primitive that always holds a number. <code>Integer</code> is a wrapper class, so the variable is a reference and may point at nothing.`]]
};
QZ.l01=[
{lv:"B",q:`Which statement about <code>String</code> is true?`,
 o:[`It is a primitive type, like <code>char</code>`,`It is an object of the <code>final</code> class <code>java.lang.String</code>, and its characters can't change`,`It is a mutable object; methods such as <code>toUpperCase()</code> change it in place`,`It must be imported before use`],
 a:1,e:`A String is an object, its class is <code>final</code>, and it is immutable. <code>java.lang</code> is imported automatically. Methods such as <code>toUpperCase()</code> return a <b>new</b> String; they never change the original.`},
{lv:"B",q:`<code>String s = "car";</code> Where do the variable and the characters live?`,
 o:[`Both on the stack`,`Both inside the String pool`,`<code>s</code> on the stack holds a reference; the String object and its <code>byte[]</code> are on the heap, and the pool points to that object`,`<code>s</code> on the heap, the characters in Metaspace`],
 a:2,e:`A local variable is a slot in the method's stack frame. It holds only a <b>reference</b>. Every String object lives on the heap. Since Java 7 the pool is a table in the heap that points to the pooled objects.`},
{lv:"B",q:`What does this print?<pre><code>String s = "java";
s.toUpperCase();
System.out.println(s);</code></pre>`,
 o:[`<code>JAVA</code>`,`<code>Java</code>`,`It doesn't compile`,`<code>java</code>`],
 a:3,e:`<code>toUpperCase()</code> returns a new String, and the result is thrown away. <code>s</code> still points to <code>"java"</code>. Write <code>s = s.toUpperCase();</code> to keep it.`},
{lv:"I",q:`What does this print?<pre><code>String a = "hi", b = "h" + "i", c = new String("hi");
String h = "h";
String d = h + "i";
System.out.println((a == b) + " " + (a == c) + " " + (a == d) + " " + (a == d.intern()));</code></pre>`,
 o:[`<code>true false false true</code>`,`<code>true false true true</code>`,`<code>false false false true</code>`,`<code>true true false false</code>`],
 a:0,e:`<code>"h" + "i"</code> is folded by javac into the literal <code>"hi"</code>, so it is the pooled object. <code>new</code> always makes a heap object. <code>h + "i"</code> uses a variable that is not <code>final</code>, so it is built at run time: a new object. <code>intern()</code> returns the pooled one.`},
{lv:"I",q:`How many String objects does <code>String s = new String("swift");</code> create, if <code>"swift"</code> was not in the pool before?`,
 o:[`One: the heap object`,`Two: the pooled <code>"swift"</code> and a separate heap object`,`Three: literal, heap object and a copy of the <code>byte[]</code>`,`None, it reuses the pool`],
 a:1,e:`The literal is resolved first (<code>ldc</code>) and pooled. Then <code>new</code> allocates a second String on the heap. The two objects <b>share</b> one <code>byte[]</code>, which is not a String object.`},
{lv:"I",q:`A request handler checks a header that may be missing (<code>null</code>). Which check never throws?`,
 o:[`<code>role.equals("admin")</code>`,`<code>role == "admin"</code>`,`<code>"admin".equals(role)</code>`,`<code>role.equalsIgnoreCase("admin")</code>`],
 a:2,e:`Calling a method on the literal is null-safe: <code>"admin".equals(null)</code> is simply <code>false</code>. Options 1 and 4 throw <code>NullPointerException</code> when <code>role</code> is null. <code>==</code> doesn't throw, but it compares references and is wrong for content.`},
{lv:"I",q:`Since Java 7, what does <code>s.intern()</code> do when the pool does <b>not</b> contain the text of <code>s</code>?`,
 o:[`Copies <code>s</code> into PermGen and returns the copy`,`Stores a reference to <code>s</code> itself in the pool and returns <code>s</code>`,`Throws <code>IllegalStateException</code>`,`Returns <code>null</code>`],
 a:1,e:`Java 6 copied the String into PermGen. Since Java 7 the pool lives in the heap and simply records a reference to the existing object, so <code>s.intern() == s</code> is <code>true</code> for the first object interned with that text.`},
{lv:"A",q:`What does this print?<pre><code>String built = new StringBuilder("ja").append("va").toString();
System.out.println(built.intern() == built);</code></pre>`,
 o:[`<code>true</code>, the first interned object becomes the pooled one`,`<code>false</code>, because <code>"java"</code> is already in the pool when the program starts`,`It doesn't compile`,`<code>true</code> only on Java 6`],
 a:1,e:`The JDK itself uses the literal <code>"java"</code> (for example in <code>java.lang</code> package names), so it is pooled before <code>main</code> runs. <code>intern()</code> returns <b>that</b> object, not <code>built</code>. With a unique text the answer would be <code>true</code>.`},
{lv:"A",q:`Which of these is <b>not</b> a reason String is immutable?`,
 o:[`Pooled Strings can be shared safely`,`The <code>hashCode</code> can be computed once and cached`,`Strings are automatically thread-safe`,`It makes <code>+</code> in a loop fast`],
 a:3,e:`Immutability is what makes <code>+</code> in a loop <b>slow</b>: every step copies the whole text into a new object. Sharing in the pool, cached hashes, thread safety and security are the real reasons.`},
{lv:"A",q:`<code>String a = "x"; String b = a + "y";</code> on JDK 9 or later. How many String objects, if nothing was pooled before?`,
 o:[`1`,`2: pooled <code>"x"</code> and <code>"xy"</code> on the heap`,`3: <code>"x"</code>, <code>"y"</code> and <code>"xy"</code>`,`4`],
 a:1,e:`<code>"x"</code> is pooled. <code>a + "y"</code> is a run-time concatenation (<code>a</code> is not <code>final</code>), so <code>"xy"</code> is a new heap object that is not pooled. Since Java 9 the constant part <code>"y"</code> lives inside the invokedynamic recipe, not as a pooled String; before Java 9 it was pooled, making 3.`}
,{lv:"B",q:`<code>String s = "Hello"; s.toUpperCase(); System.out.println(s.substring(1, 3));</code> What is printed?`,
 o:[`<code>EL</code>`,`<code>el</code>`,`<code>ell</code>`,`<code>ELL</code>`],
 a:1,e:`<code>toUpperCase()</code> returned a new String that nobody kept, so <code>s</code> is still <code>"Hello"</code>. <code>substring(1, 3)</code> keeps indexes 1 and 2 (the end index is excluded): <code>"el"</code>. Try both in the methods playground.`},
{lv:"I",q:`<code>"a.b.c".split(".")</code> returns…`,
 o:[`<code>["a", "b", "c"]</code>`,`<code>["a.b.c"]</code>`,`an empty array`,`it throws PatternSyntaxException`],
 a:2,e:`<code>split</code> takes a <b>regex</b>, and <code>.</code> matches every character, so every piece is empty and the trailing empty strings are removed: an empty array. Write <code>split("\\\\.")</code>, or avoid the regex with <code>replace</code>. The same trap exists for <code>replaceAll</code>, <code>replaceFirst</code> and <code>matches</code>.`}
];
RC.l01={
 d1:[[`What is a String in Java?`,`An immutable object of the <code>final</code> class <code>java.lang.String</code>: a sequence of characters stored in a <code>byte[]</code>, with a cached hash.`],
     [`Where do a String variable, the String object and the pool live?`,`The variable is a reference on the stack; the object and its <code>byte[]</code> are on the heap; the pool is a heap table (since Java 7) pointing at the pooled objects.`],
     [`What does <code>==</code> compare for Strings, and what does <code>equals</code> compare?`,`<code>==</code> compares references (same object?); <code>equals</code> compares the characters.`]],
 d3:[[`Why does <code>"hel" + "lo" == "hello"</code> print true but <code>part + "lo" == "hello"</code> print false?`,`The first is a compile-time constant that javac folds into the pooled literal. The second is built at run time, a new heap object. A <code>final</code> variable makes it a constant again.`],
     [`Why does <code>s.toUpperCase();</code> on its own change nothing?`,`String methods return a new String; the original can't change. Reassign: <code>s = s.toUpperCase();</code>.`],
     [`What changed about <code>intern()</code> in Java 7?`,`The pool moved from PermGen to the heap, so <code>intern()</code> stores a reference to the existing object instead of copying it, and pooled Strings can be garbage-collected.`]],
 d7:[[`Explain to an interviewer why String is immutable.`,`Safe sharing in the pool, a hash that can be cached (safe map keys), thread safety without locks, and security (paths, class names, URLs can't change after checks).`],
     [`How many objects does <code>new String("a") + new String("b")</code> create, and where?`,`Five: <code>"a"</code> and <code>"b"</code> pooled, two heap copies made by <code>new</code>, and <code>"ab"</code> on the heap (not pooled).`],
     [`A service compares a user-supplied value with a constant. Write the safe check and say why.`,`<code>"CONST".equals(value)</code> (or <code>Objects.equals</code>): content-based and null-safe, unlike <code>==</code> and unlike <code>value.equals(...)</code> on a null.`]]
};

/* Lesson 02 (What is a Class and an Object?). Every output was checked on JDK 25. */
QZ.l02=[
{lv:"B",q:`Which statement is true?`,
 o:[`A class is an object that lives on the heap`,`A class is a blueprint (a type); an object is one instance built from it with <code>new</code>`,`An object and a class are the same thing`,`Every class can have only one object`],
 a:1,e:`The class describes fields and methods once; <code>new</code> builds as many objects from it as you like, each with its own field values.`},
{lv:"B",q:`What does this print?<pre><code>Car a = new Car("Swift", "red");
Car b = new Car("Nexon", "blue");
a.accelerate(40);
System.out.println(b.speed);</code></pre>`,
 o:[`40`,`0`,`null`,`A compile error`],
 a:1,e:`Each object has its <b>own</b> copy of the instance fields. Only <code>a</code>'s speed changed; <code>b.speed</code> is still its default, 0.`},
{lv:"B",q:`<code>Car c = a;</code> How many Car objects are there now (if <code>a</code> already pointed to one)?`,
 o:[`One: <code>c</code> is a second reference to the same car`,`Two: <code>c</code> is a copy of the car`,`Zero: <code>a</code> loses its car`,`It depends on <code>equals</code>`],
 a:0,e:`Assigning a reference copies the <b>arrow</b>, not the object. <code>a == c</code> is true, and a change through <code>c</code> is visible through <code>a</code>.`},
{lv:"B",q:`What is the default value of a <code>String</code> field and an <code>int</code> field in a new object?`,
 o:[`<code>""</code> and <code>0</code>`,`<code>null</code> and <code>0</code>`,`<code>null</code> and <code>null</code>`,`They have no value: reading them is a compile error`],
 a:1,e:`Fields start at defaults: references <code>null</code>, numbers 0, <code>boolean</code> false. Only <b>local</b> variables have no default.`},
{lv:"I",q:`What does this print?<pre><code>class Bike {
    String model;
    Bike(String model) { model = model; }
}
System.out.println(new Bike("Duke").model);</code></pre>`,
 o:[`Duke`,`null`,`model`,`A compile error`],
 a:1,e:`Inside the constructor, <code>model</code> means the parameter, so <code>model = model</code> assigns it to itself. The field stays <code>null</code>. Write <code>this.model = model;</code>.`},
{lv:"I",q:`A class declares only <code>Car(String model)</code>. What does <code>new Car()</code> do?`,
 o:[`Creates a Car with <code>model = null</code>`,`Fails to compile: the default constructor is added only when a class declares none`,`Throws a NullPointerException`,`Creates a Car with <code>model = ""</code>`],
 a:1,e:`javac: <i>constructor Car in class Car cannot be applied to given types</i>. Write <code>Car()</code> yourself, ideally as <code>this("Unknown")</code>.`},
{lv:"I",q:`What does this print?<pre><code>static void tune(Car car) {
    car.speed = 100;
    car = new Car("Spare");
}
Car c = new Car("Swift");
tune(c);
System.out.println(c.model + " " + c.speed);</code></pre>`,
 o:[`Spare 100`,`Swift 0`,`Swift 100`,`Spare 0`],
 a:2,e:`The method gets a <b>copy of the reference</b>. Following it changes the caller's car (speed 100); re-pointing the copy to a new car does nothing to <code>c</code>.`},
{lv:"I",q:`<code>static int built;</code> is incremented in the constructor. After three <code>new Car(…)</code>, what is <code>Car.built</code>?`,
 o:[`1 in every car`,`3, one shared copy for the whole class`,`0, static fields can't change`,`A compile error: static fields can't be used in constructors`],
 a:1,e:`A static field belongs to the class: one copy shared by all objects. Each constructor call adds 1 to the same counter.`},
{lv:"A",q:`A class <code>Car</code> overrides neither <code>toString</code> nor <code>equals</code>. With <code>a</code> and <code>b</code> built from the same arguments, which is true?`,
 o:[`<code>println(a)</code> shows the field values, and <code>a.equals(b)</code> is true`,`<code>println(a)</code> shows <code>Car@</code> plus a hex hash, and <code>a.equals(b)</code> is false`,`Both lines fail to compile`,`<code>a.equals(b)</code> is true because the fields match`],
 a:1,e:`Without overrides you get <code>Object</code>'s versions: <code>toString</code> = class name @ hash in hex, <code>equals</code> = <code>==</code> (same object?).`},
{lv:"A",q:`Why does this fail to compile?<pre><code>class Car {
    int speed;
    public static void main(String[] args) {
        speed = 10;
    }
}</code></pre>`,
 o:[`<code>speed</code> is not initialised`,`<code>main</code> must not be inside a class`,`<code>main</code> is static: there is no object, so no <code>speed</code> to set (non-static variable cannot be referenced from a static context)`,`<code>int</code> fields must be <code>final</code>`],
 a:2,e:`A static method has no <code>this</code>. Create an object first: <code>Car c = new Car(); c.speed = 10;</code>.`}
];
RC.l02={
 d1:[[`Class vs object in one sentence each?`,`A class is a blueprint (fields + methods, a type); an object is one instance of it, built with <code>new</code>, living on the heap with its own field values.`],
     [`What three things does <code>new Car("Swift")</code> do?`,`Allocate on the heap with default values, run the constructor (<code>this</code> = the new object), return the reference.`],
     [`What does <code>Car c = a;</code> copy?`,`The reference. Still one car, two names.`]],
 d3:[[`Why does <code>model = model;</code> in a constructor leave the field null, and what is the fix?`,`The parameter shadows the field, so it assigns the parameter to itself. <code>this.model = model;</code>.`],
     [`When does the compiler add a default constructor?`,`Only when the class declares no constructor at all.`],
     [`Default values of fields vs local variables?`,`Fields: 0 / 0.0 / false / character 0 / null. Locals: none; reading an unassigned local is a compile error.`]],
 d7:[[`Explain static vs instance to an interviewer.`,`Instance members belong to each object (one copy each, need an object, have <code>this</code>). Static members belong to the class (one shared copy, used via the class name, no <code>this</code>).`],
     [`Where do the object, its reference and its class live?`,`Object on the heap; a local reference in the stack frame; class metadata and method code in Metaspace, loaded once.`],
     [`What do <code>Object</code>'s <code>toString</code> and <code>equals</code> do, and what must you override with <code>equals</code>?`,`<code>ClassName@hexHash</code> and <code>==</code>. Override <code>hashCode</code> together with <code>equals</code>.`]]
};

/* Patterns P00 (Foundations and SOLID). Every output was checked on JDK 25. */
QZ.p00=[
{lv:"B",q:"What is a design pattern?",o:["A library you add to the project","A named, reusable solution to a recurring design problem, written in your own classes","A sorting or searching algorithm","A Java language feature"],a:1,e:"A pattern is an idea (roles for classes and objects) that you implement yourself each time. It is not imported, and it is about structure, not algorithms."},
{lv:"B",q:"Which family does a pattern about <b>how objects are created</b> belong to?",o:["Structural","Behavioral","Creational","Architectural"],a:2,e:"Creational: Singleton, Factory Method, Builder, Abstract Factory, Prototype. Structural is about composing objects, behavioral about how they interact."},
{lv:"B",q:"In a class diagram, what does a <b>dashed line with a hollow triangle</b> mean?",o:["extends","implements","has-a","calls"],a:1,e:"Dashed + hollow triangle = implements (the triangle points at the interface). Solid + hollow triangle = extends. A diamond marks has-a at the owner; a plain arrow means calls / uses."},
{lv:"B",q:"Which can an <b>interface</b> NOT have?",o:["A default method with a body","A static method","An instance field holding per-object state","A constant (static final field)"],a:2,e:"Interface fields are implicitly <code>public static final</code>: constants only. Per-object state needs a class (often an abstract class)."},
{lv:"B",q:"What does the <b>S</b> in SOLID say?",o:["A class should have only one method","A class should have one reason to change","A class should be small","A class should be static"],a:1,e:"One reason to change = one actor or concern it answers to. Several methods about the same concern are fine."},
{lv:"I",q:"What does this print?<pre><code>Car suv = new Car(\"SUV\", new PetrolEngine());\nsuv.setEngine(new ElectricEngine());\nsuv.start();</code></pre>(<code>start()</code> prints <code>body + \": \" + engine.sound()</code>.)",o:["SUV: petrol engine, vroom","SUV: electric motor, hum","A compile error: the engine is final","Both lines"],a:1,e:"Composition: the car delegates to whatever Engine object is in its field at the moment, and <code>setEngine</code> swapped it at run time."},
{lv:"I",q:"A price calculator has an if / else chain over offer names. Adding a student offer means editing it. Which principle is broken?",o:["Single Responsibility","Open / Closed","Liskov Substitution","Interface Segregation"],a:1,e:"Open for extension, closed for modification: put each offer behind a <code>Discount</code> interface and a new offer is a new class. That shape is the Strategy pattern."},
{lv:"I",q:"<code>ElectricCar extends Car</code>, and its <code>refuel()</code> throws <code>UnsupportedOperationException</code>. Which principle is broken?",o:["Dependency Inversion","Interface Segregation","Liskov Substitution","Open / Closed"],a:2,e:"Code written for <code>Car</code> can't use an <code>ElectricCar</code> safely: the subtype is not substitutable. Fix the abstraction (<code>topUp()</code>) so every subtype can keep the promise."},
{lv:"I",q:"With <code>Repairer m = new Mechanic(\"Ravi\");</code> (Repairer declares only <code>repair</code>), what does <code>m.sell(\"Nexon\");</code> do?",o:["Runs and prints nothing","Throws UnsupportedOperationException at run time","Does not compile: Repairer has no sell()","Calls Seller.sell"],a:2,e:"The variable's type decides which methods you can call. Small role interfaces (ISP) turn the wrong call into a compile error instead of a crash."},
{lv:"I",q:"Why is <code>List&lt;String&gt; cars = new ArrayList&lt;&gt;();</code> preferred over <code>ArrayList&lt;String&gt; cars = …</code>?",o:["It is faster","ArrayList cannot be a variable type","The code that uses <code>cars</code> depends only on the List promise, so the class can change in one place","List allows null and ArrayList does not"],a:2,e:"Program to an interface: name the concrete class only where the object is created."},
{lv:"A",q:"What is the difference between <b>Dependency Inversion</b> and <b>Dependency Injection</b>?",o:["They are two names for the same thing","Inversion is the principle (depend on abstractions); injection is a technique that applies it (pass the dependency in)","Injection is the principle and inversion is Spring's implementation","Inversion is about inheritance, injection about interfaces"],a:1,e:"DIP: both high- and low-level code depend on an abstraction. DI: the dependency is handed in (constructor, setter, field). Spring's IoC container performs the injection."},
{lv:"A",q:"Bodies (SUV, sedan, hatchback) × engines (petrol, electric, hybrid, diesel) with inheritance need 12 leaf classes. With composition (Car has-a Engine), how many classes do you need for the bodies and engines?",o:["12","24","1 Car class + 4 engine classes","16: one per body, engine and pair"],a:2,e:"The body becomes a value in a field of one Car class, and each engine is one class behind the Engine interface: 1 + 4 (plus the interface). Classes grow as a sum, not a product."},
{lv:"B",q:"<code>Discount discount = new LoyaltyDiscount();</code> then <code>discount.apply(700000)</code>. Which <code>apply</code> runs?",o:["Discount's, because that is the declared type","LoyaltyDiscount's, because that is the object's class","Neither: an interface method has no body, so it fails at run time","Whichever class was compiled last"],a:1,e:"The compiler checks the call against the declared type (Discount has apply), but at run time the JVM runs the method of the object's class. This run-time choice is dynamic dispatch: it prints 680000."},
{lv:"I",q:"<code>Car car = new ElectricCar(\"Nexon EV\");</code> and a Showroom has <code>welcome(Car)</code> and <code>welcome(ElectricCar)</code>. What does <code>showroom.welcome(car)</code> call?",o:["welcome(ElectricCar), because the object is an ElectricCar","welcome(Car), because overloads are chosen at compile time from the declared type","It does not compile: the call is ambiguous","It throws ClassCastException"],a:1,e:"Overloads are picked by the compiler from the declared types of the arguments; car is declared as Car. Only overrides are chosen at run time by the object. Casting, welcome((ElectricCar) car), selects the other overload."},
{lv:"B",q:"Which of these is a <b>functional interface</b>?",o:["An interface with one abstract method and two default methods","An interface with two abstract methods","An abstract class with one abstract method","Any interface annotated @Override"],a:0,e:"A functional interface has exactly one abstract method; default and static methods do not count. @FunctionalInterface only asks the compiler to check it. A lambda can implement an interface, never an abstract class."},
{lv:"A",q:"Inside an instance method of Showroom, what does <code>this</code> refer to in a lambda, and in an anonymous class?",o:["Both refer to the Showroom object","Lambda: the Showroom object; anonymous class: the anonymous object itself","Lambda: the lambda object; anonymous class: the Showroom object","Both refer to the anonymous or lambda object"],a:1,e:"A lambda does not introduce a new scope for this: it means the enclosing Showroom. An anonymous class is a real class, so this is its own instance (the program prints \"lambda this: Showroom\" and \"anonymous this: anonymous class\")."}
];
RC.p00={"d1":[["What is a design pattern, in one sentence?","A named, reusable solution to a recurring design problem: roles for classes and objects that you implement yourself."],["The four arrows of a class diagram?","Implements (dashed, hollow triangle), extends (solid, hollow triangle), has-a (diamond at the owner), calls (plain arrow)."],["SOLID, one line per letter?","One reason to change · extend, don't modify · subtypes keep promises · small interfaces · depend on abstractions."],["Override vs overload: who decides, and when?","Override (same signature): the object's class, at run time (dynamic dispatch). Overload (different parameter types): the compiler, at compile time, from the declared types."]],
 "d3":[["Why favour composition over inheritance?","Inheritance is fixed at compile time and multiplies classes per combination; composition swaps parts at run time and grows as a sum."],["How do you spot a Liskov violation?","Overrides that throw or do nothing, callers checking instanceof, subtypes needing stricter inputs."],["Interface vs abstract class?","Interface: a capability, many per class, no state. Abstract class: a shared base with state and code, one per class."],["Write one PriceRule four ways.","Named class: class FestivalRule implements PriceRule {…}. Anonymous: new PriceRule() { public long apply(long p) {…} }. Lambda: p -> p * 90 / 100. Method reference: Lambdas::festival."]],
 "d7":[["Refactor an if / else over offer types: which principle and which pattern?","Open/Closed; an interface per rule (Strategy)."],["DIP vs DI vs IoC?","Principle (depend on abstractions) · technique (pass dependencies in) · framework controls creation and calls (Spring container)."],["When should you NOT use a pattern?","When the variation it plans for does not exist yet: it only adds classes and indirection."],["A Checkout with if / else over card, UPI, cash keeps growing. Name the smell and the fix.","A growing type-code conditional (breaks OCP, tight coupling). Fix: interface Payment, one class per type, Checkout gets a Payment through its constructor: the Strategy pattern."]]};
QZ.p03=[
{lv:"B",q:"What is the intent of the State pattern?",o:["Let the client pick one of several interchangeable algorithms","Let an object change its behaviour when its internal stage changes, by delegating to a state object","Make sure a class has exactly one instance","Fix the steps of an algorithm in a base class"],a:1,e:"State: the context forwards requests to its current state object, and swapping that object changes the behaviour."},
{lv:"B",q:"In the dealership example, which class is the context?",o:["OrderState","Booked","Order","Cancelled"],a:2,e:"Order is the object the client talks to; it holds the current OrderState and delegates to it."},
{lv:"B",q:"Which code smell usually points to the State pattern?",o:["The same status field switched on in several methods, growing with each new status","A class with many constructor parameters","Two unrelated interfaces that must work together","A loop over a collection"],a:0,e:"Several methods each switching on one status field is the classic State smell."},
{lv:"B",q:"In OrderAfter.java, what happens when deliver() is called on a Paid order?",o:["Paid.deliver moves the order to Delivered","Order's switch rejects it","A NullPointerException is thrown","Paid does not override deliver, so the interface's default runs and prints \"cannot deliver an order that is Paid\""],a:3,e:"Illegal actions fall through to the default method in OrderState, which calls o.reject(\"deliver\")."},
{lv:"I",q:"In the class-based design, who decides that after Booked comes Paid?",o:["The client, by calling setState","Booked.pay, which creates new Paid() and calls o.moveTo","Order.pay, with a switch","The JVM"],a:1,e:"The states own the transitions: Booked's pay() creates the next state and asks the context to move."},
{lv:"I",q:"State and Strategy have the same class diagram. What really separates them?",o:["State uses an abstract class, Strategy an interface","Strategy objects are always lambdas","With State the states replace each other as the object's stage changes; with Strategy the client chooses the object from outside","State is creational, Strategy is behavioral"],a:2,e:"Who changes the object: the states themselves (State) versus the client (Strategy). Both are behavioral."},
{lv:"I",q:"A new status \"Inspected\" goes between Allocated and Delivered with a new action inspect(). Which existing classes change?",o:["OrderState (one default), Order (one delegating line) and Allocated; Inspected is new","Every state class","Only Order","None: State needs no edits ever"],a:0,e:"A new action touches the interface and the context; a new status is a new class plus an edit in the state that leads to it."},
{lv:"I",q:"How should an order's state be stored in a database?",o:["As the enum ordinal (0, 1, 2…)","By serialising the state object","As a stable name such as 'PAID' (e.g. @Enumerated(EnumType.STRING)), rebuilt into the state object on load","It cannot be stored"],a:2,e:"Store the name; ordinals shift when a status is inserted. On load map the name back (valueOf or a small factory)."},
{lv:"I",q:"Is java.lang.Thread.State an example of the GoF State pattern?",o:["Yes, Thread delegates start() to it","No: it is an enum that reports the thread's stage; Thread's behaviour is not delegated to it","Yes, because it has six constants","No, it is a Singleton"],a:1,e:"Thread.State is an enum of states you read with getState(); there is no delegation to state objects."},
{lv:"A",q:"Why can the enum constants in OrderEnum.java be shared by every order, while an OnHold state that remembers where to resume cannot?",o:["Enums are faster","OnHold would need to be abstract","Shared objects must be records","The enum constants hold no per-order data; OnHold holds a per-order field (the previous state)"],a:3,e:"Stateless states can be shared (one per state, like a Singleton); a state with per-order data must be created per order."},
{lv:"A",q:"Two requests call pay() and cancel() on the same order at the same moment. What is the risk and a fix?",o:["No risk: state objects are immutable","Both may read the old state and act on it (check-then-act); synchronize the transition or use optimistic locking (@Version)","A deadlock is guaranteed; remove the State pattern","The JVM queues the calls automatically"],a:1,e:"Read-decide-write is a race. Guard it with synchronized, compareAndSet on an AtomicReference, or a DB transaction with @Version."},
{lv:"A",q:"With a sealed interface and records for each state, what does a switch with no default give you?",o:["The compiler checks every permitted state is handled, so adding a state breaks the build until all switches handle it","Faster dispatch than virtual calls","Automatic persistence","Nothing: a default is required"],a:0,e:"Pattern-matching switches over a sealed hierarchy are exhaustive; a new record forces every switch to be updated."}
];
RC.p03={d1:[["State pattern in one sentence?","The context delegates every request to its current state object; changing stage means swapping that object."],["Where does \"not allowed\" live in OrderAfter.java?","In the OrderState interface's default methods, which call o.reject(action); states override only what they allow."],["Who decides the next state?","The current state: it creates the next state and calls o.moveTo(next, note)."]],
d3:[["State vs Strategy?","Same diagram; Strategy is chosen by the client from outside, State objects replace each other as the stage changes."],["When is an enum and a switch enough?","Few stages, one or two actions depend on them, and the list rarely changes."],["How do you persist the state?","Store its name (EnumType.STRING), never the ordinal; rebuild the state object from the name on load."]],
d7:[["Why can enum states be shared?","They hold no per-order data, so one constant per state serves every order (Singleton-like)."],["How do you make transitions safe under concurrency?","Guard check-then-act: synchronized, compareAndSet, or a transaction with optimistic locking (@Version)."],["Strategy vs Template Method vs State: who chooses?","Strategy: the client. Template Method: the subclass you create. State: the states themselves at run time."]]};
QZ.p01=[
{lv:"B",q:"What is the intent of the Strategy pattern?",o:["Make sure a class has only one instance","Put each interchangeable behaviour in its own class behind one interface, and let the client pick one","Notify many objects when one object changes","Build a complex object step by step"],a:1,e:"Strategy is about interchangeable behaviours (discount rules) behind one interface, chosen from outside the context."},
{lv:"B",q:"In the dealership code, which class is the <b>Context</b>?",o:["Discount","FestivalDiscount","Checkout","main"],a:2,e:"Checkout holds a Discount field and delegates the varying work to it. Discount is the Strategy, FestivalDiscount a ConcreteStrategy, main the client."},
{lv:"B",q:"Which smell usually tells you Strategy may help?",o:["A growing if / else (or switch) on a type code such as an offer name","A class with too many getters","A method longer than ten lines","A class with no fields"],a:0,e:"Each new offer adds a branch to tested code. Strategy turns each branch into a class behind one interface."},
{lv:"B",q:"With Strategy in place, what do you change to add a <code>StudentDiscount</code>?",o:["Add a new branch to Checkout.total","Add a subclass of Checkout","Edit every existing discount class","Add a new class that implements Discount, and hand it in from the client"],a:3,e:"A new rule is a new class; Checkout is closed for modification and open for extension."},
{lv:"I",q:"<code>Checkout checkout = new Checkout(new FestivalDiscount()); checkout.setDiscount(new LoyaltyDiscount()); checkout.print(700000);</code> prints what? (loyalty = Rs 20000 off)",o:["Festival 10%: Rs 630000","Loyalty Rs 20000: Rs 680000","Loyalty Rs 20000: Rs 610000","No discount: Rs 700000"],a:1,e:"setDiscount replaced the strategy on the same Checkout, so print uses LoyaltyDiscount: 700000 - 20000 = 680000."},
{lv:"I",q:"Strategy vs State: what is the key difference?",o:["In Strategy the client picks the behaviour from outside; in State the object switches its own state objects as events happen","Strategy uses inheritance, State uses composition","State has no interface","Strategy can only have two variants"],a:0,e:"The class diagrams look alike; the difference is who chooses and when. Strategies usually don't know each other; states often pick the next state."},
{lv:"I",q:"Strategy vs Template Method?",o:["Both use inheritance","Template Method can be swapped at run time, Strategy cannot","They are the same pattern","Strategy uses composition (swap an object at run time); Template Method uses inheritance (a subclass fills in steps, fixed at compile time)"],a:3,e:"Template Method: a base class fixes the skeleton, subclasses override steps. Strategy: the whole varying algorithm is a separate, swappable object."},
{lv:"I",q:"Which JDK call is a textbook use of Strategy?",o:["String.valueOf(x)","Math.max(a, b)","list.sort(Comparator.comparingLong(Car::price))","new ArrayList&lt;&gt;()"],a:2,e:"List.sort is the context; the Comparator is the strategy that decides the order. Pass another comparator and the same sort code orders differently."},
{lv:"I",q:"Your Discount interface has exactly one abstract method. What does that allow?",o:["Nothing special","Discount can no longer have implementing classes","Checkout no longer needs a field","Strategies can be written as lambdas or method references, because it is a functional interface"],a:3,e:"A single-abstract-method interface is a functional interface: <code>Discount festival = p -> p * 90 / 100;</code> is a strategy object. Default methods such as andThen don't count."},
{lv:"A",q:"In a Spring Boot app, how can CheckoutService choose a DiscountPolicy by offer code without an if / else?",o:["Inject Map&lt;String, DiscountPolicy&gt;: Spring fills it with every DiscountPolicy bean keyed by bean name, then look the code up","Use @Autowired on a static field","Create each policy with new inside total()","Make DiscountPolicy an abstract class"],a:0,e:"Spring injects all beans of a type as a List or a Map keyed by bean name. A new @Component(\"student\") becomes a new offer with no edit to the service."},
{lv:"A",q:"Offers must stack (festival, then loyalty) and the list per city comes from a database. Best design?",o:["One Checkout subclass per combination","A branch per combination in Checkout","Keep Strategy: map each code to a Discount and compose them (e.g. andThen) into one Discount for Checkout","Switch to the State pattern"],a:2,e:"Combinations explode for branches or subclasses. Strategies compose: 700000 → festival 630000 → loyalty 610000, and Checkout still sees one Discount."}
];
RC.p01={"d1":[["Name the four roles in Strategy and the dealership class for each.","Client = main, Context = Checkout, Strategy = Discount (interface), ConcreteStrategy = FestivalDiscount, LoyaltyDiscount, CorporateDiscount, NoDiscount."],["What does delegation mean in Strategy?","The context does not compute the varying part itself; it calls the strategy it holds (total → discount.apply(price))."],["What is the analogy?","A car's drive modes: same car (context), the driver (client) turns the knob to Eco, Sport or Snow (concrete strategies), all fitting one slot (the strategy interface)."]],"d3":[["Strategy vs State in one sentence?","Strategy: the client picks the behaviour from outside. State: the object changes its own state object as events happen."],["Three ways to choose the strategy at run time?","A factory with one switch at the edge, a Map&lt;String, Strategy&gt; registry (or an enum), or dependency injection (Spring injects a List or Map of beans)."],["When is a lambda enough and when do you want a class?","Lambda: one-line rule, no data, no name. Class or record: the rule has data (PercentOff(15)), several methods (label), dependencies or its own tests."]],"d7":[["How does Strategy follow Open / Closed and Dependency Inversion?","New rule = new class, Checkout unchanged (OCP). Checkout depends on the Discount abstraction; the concrete rule is injected (DIP)."],["When would you not use Strategy?","Two or three stable cases (keep the if / else), variants that differ only by a number (use a parameter), or behaviour that changes by itself with the object's status (State)."],["Is it safe to share one strategy instance between threads?","Yes if it is stateless (all four discounts); not if it has mutable fields. A context with a setter shared between threads is a race: prefer a final field and a new context per request."]]};
QZ.p02=[
{lv:"B",q:"In Template Method, which class decides the <b>order</b> of the steps?",o:["Each subclass, in its own inspect()","The client that calls inspect()","The base class, in the template method","Whichever class was loaded first"],a:2,e:"The base class writes the order once, in the template method (<code>inspect()</code>). Subclasses fill in only the steps that vary."},
{lv:"B",q:"Why is <code>inspect()</code> declared <code>final</code> in <code>PreDeliveryInspection</code>?",o:["So that subclasses cannot reorder or skip steps","So that it runs faster","Because abstract classes require it","So that it can be called without an object"],a:0,e:"The order is the rule of the pattern. <code>final</code> lets the compiler stop a subclass from overriding <code>inspect()</code> and, for example, signing off before the road test."},
{lv:"B",q:"What is the difference between an abstract step and a <b>hook</b>?",o:["A hook must be overridden; an abstract step may be","They are two names for the same thing","A hook is private; an abstract step is public","A hook has a default body and may be overridden; an abstract step has no body and must be"],a:3,e:"<code>modelChecks()</code> is abstract: every subclass must write it. <code>needsRoadTest()</code> is a hook: it returns <code>true</code> by default, and a subclass may override it."},
{lv:"B",q:"The \"Hollywood principle\" in Template Method means…",o:["the subclass calls the base class whenever it needs a step","the base class calls the subclass's steps (\"don't call us, we'll call you\")","every method must be public","only one subclass may exist"],a:1,e:"Control stays in the base class: <code>inspect()</code> calls <code>modelChecks()</code>, which is implemented in the subclass. The subclass never drives the flow."},
{lv:"I",q:"<code>new EvInspection().inspect(\"Nexon EV\")</code>: which line comes from the <b>subclass</b>?",o:["base  : bay booked","base  : tyres, lights, wipers, brake fluid","ev    : battery health, charge port","base  : signed off"],a:2,e:"Booking, common checks and sign-off are private steps of the base class. <code>modelChecks()</code> is the EV's own step (and the EV also overrides <code>roadTest()</code>)."},
{lv:"I",q:"A demo car overrides <code>needsRoadTest()</code> to return <code>false</code>. What changes in its output?",o:["Nothing: hooks are ignored","The road-test line is skipped; every other step still runs in order","The program does not compile, because inspect() is final","Sign-off is skipped too"],a:1,e:"The template method checks the hook: <code>if (needsRoadTest()) roadTest();</code>. Only that step is skipped; the order of the rest is untouched."},
{lv:"I",q:"Template Method vs Strategy: which statement is right?",o:["Both use composition","Strategy needs an abstract class; Template Method needs an interface","Template Method can change the steps at run time; Strategy cannot","Template Method uses inheritance and the variant is fixed when you pick the class; Strategy uses composition and can be swapped at run time"],a:3,e:"Same goal (vary part of a behaviour), different tool. Inheritance fixes the variant at <code>new</code> time; a Strategy field can be replaced while the program runs."},
{lv:"I",q:"In <code>java.io.InputStream</code>, <code>read(byte[], int, int)</code> calls the abstract <code>read()</code>. Which role is <code>read()</code>?",o:["A primitive operation that subclasses implement","The template method","A hook with a default","A factory method"],a:0,e:"<code>read(byte[],int,int)</code> is the template (the loop); the one-byte <code>read()</code> is the abstract step each stream (e.g. <code>FileInputStream</code>) fills in."},
{lv:"I",q:"Which sign says it is time to replace Template Method with Strategy?",o:["You have two subclasses","The base class has a final method","Each branch must switch steps on or off at run time and the variations combine","A step prints a line"],a:2,e:"Run-time choice and combining variations (car type × branch options) explode into subclasses. Composition (steps as strategies or lambdas) handles that; a few stable subclasses do not need it."},
{lv:"A",q:"Why should the base-class <b>constructor</b> not call <code>modelChecks()</code>?",o:["Constructors cannot call methods","It would make inspect() non-final","Abstract methods cannot be called from a constructor at compile time","The subclass's fields are not initialised yet, so the overridden step runs on a half-built object"],a:3,e:"Java runs the base constructor before the subclass's field initialisers, so an overridden step called from it sees <code>null</code> or <code>0</code>. Call the template from a normal method after construction."},
{lv:"A",q:"Passing the varying steps as lambdas (<code>Runnable</code>, <code>BooleanSupplier</code>) to one method turns the design into…",o:["a Strategy-style design: behaviour is composed in at run time instead of inherited","still Template Method, unchanged","a Singleton","an Abstract Factory"],a:0,e:"Once the steps arrive as objects, the class no longer needs subclasses: the variation is composed in, which is Strategy's idea. Spring's <code>JdbcTemplate</code> works this way (the callback variant)."}
];
RC.p02={"d1":[["Template Method in one sentence?","A base class writes the order of the steps once, in a final method, and subclasses fill in only the steps that vary."],["Abstract step vs hook vs private step?","Abstract: must be filled in. Hook: has a default, may be overridden. Private: fixed, cannot be changed."],["What is the Hollywood principle?","The base class calls the subclass's steps; the subclass never drives the flow (\"don't call us, we'll call you\")."]],"d3":[["Why is the template method final?","The order is the rule; final lets the compiler stop a subclass from reordering or skipping steps."],["Template Method vs Strategy?","Inheritance and a compile-time choice vs composition and a run-time choice; same goal of varying part of a behaviour."],["Two JDK examples?","InputStream.read(byte[],int,int) on the abstract read(); AbstractList (implement get and size). HttpServlet.service() dispatching to doGet/doPost."]],"d7":[["When would you switch from Template Method to Strategy?","When the choice must happen at run time, or variations combine and the subclasses multiply."],["Why must a base constructor not call an overridable step?","The subclass's fields are not initialised yet; the step runs on a half-built object."],["How does JdbcTemplate relate to the pattern?","It is the callback variant: the fixed JDBC steps live in JdbcTemplate and the varying step is passed in as a callback object, not overridden."]]};
QZ.p04=[{"lv":"B","q":"What problem does Factory Method solve in the dealership?","o":["Many places choose the car class with their own if / else and new","Cars are too slow to build","Cars cannot have discounts","Showrooms cannot sell more than one car"],"a":0,"e":"The decision of which class to new is scattered. Factory Method puts it in one overridable method."},
{"lv":"B","q":"In Factory Method, which part decides which concrete class is created?","o":["The client's if / else","The Product interface","The ConcreteCreator subclass, in its override of the factory method","The compiler"],"a":2,"e":"CityShowroom.createCar() returns a PetrolCar; EvShowroom.createCar() returns an EvCar."},
{"lv":"B","q":"Which of these is a factory method in our code?","o":["Showroom.sellCar()","Showroom.createCar()","Car.price()","main()"],"a":1,"e":"createCar() is the method whose job is to return a new product."},
{"lv":"B","q":"Is a Simple Factory (one static CarFactory.create(fuel)) a GoF pattern?","o":["Yes, it is the Factory Method pattern","Yes, it is Abstract Factory","No, it is Singleton","No, it is a common idiom and a stepping stone"],"a":3,"e":"The GoF book does not include it. It is useful but it is one class with a switch."},
{"lv":"I","q":"Adding CNG with Factory Method means:","o":["Editing the switch in every caller","Adding CngCar and CngShowroom and editing nothing existing","Editing Showroom.sellCar()","Adding a branch to each existing showroom"],"a":1,"e":"A new product and a new creator subclass: Open / Closed."},
{"lv":"I","q":"Why does sellCar() run EvShowroom.createCar() when the call is written in Showroom?","o":["Because of method overloading","Because createCar is static","Because of dynamic dispatch: the actual object is an EvShowroom","Because Showroom is an interface"],"a":2,"e":"The method is chosen by the run-time class of the object, not the type of the variable."},
{"lv":"I","q":"What is the difference between a static factory method (List.of) and the GoF Factory Method?","o":["A static one cannot be overridden by subclasses, the GoF one is an overridable method","None, they are the same thing","The static one always creates a new object","The GoF one is only for collections"],"a":0,"e":"Static factories give names and caching (Effective Java item 1) but no 'subclass decides'."},
{"lv":"I","q":"What does Integer.valueOf(127) == Integer.valueOf(127) show?","o":["Always false","A compile error","true for every int","true, because small values are cached by the static factory method"],"a":3,"e":"valueOf returns cached instances for small values; 1000 gives false."},
{"lv":"I","q":"How can a Map<String, Supplier<Car>> replace creator subclasses?","o":["It stores cars, not ways to create them","Each entry is a way to create a car, such as EvCar::new, chosen by name","It makes cars immutable","It needs reflection"],"a":1,"e":"A Supplier is 'how to build one'. Use subclasses when there is a routine around the creation."},
{"lv":"I","q":"Why is Factory Method often one step of a Template Method?","o":["Both use static methods","Template Method creates objects","They are the same pattern","sellCar() is a fixed routine and createCar() is the step that subclasses fill in"],"a":3,"e":"The routine (inspect, deliver) is fixed; the creation varies per subclass."},
{"lv":"A","q":"How do you test sellCar() without any real car class?","o":["You cannot","Subclass Showroom and override createCar() to return a stub Car","Make createCar() static","Use reflection to set the fuel"],"a":1,"e":"Creation is a method, so a fake creator replaces just that step."},
{"lv":"A","q":"Why is calling an overridable factory method from a constructor risky?","o":["The subclass fields are not initialised yet when the base constructor runs","It is slower","Constructors cannot call methods","It creates two objects"],"a":0,"e":"The base constructor runs first, so the override sees default values."}];
RC.p04={"d1":[["What is a factory method?","A method that creates and returns the product, declared in a base class and overridden by subclasses."],["Name the four roles.","Product, ConcreteProduct, Creator, ConcreteCreator."],["What is the analogy?","A factory machine with an order slot: the counter takes the order, the machine decides what to build."]],"d3":[["Simple Factory vs Factory Method?","Simple Factory is one switch in one class (not GoF). Factory Method is an overridable method: the subclass decides."],["What changes when CNG arrives?","A new CngCar and CngShowroom; nothing existing is edited."],["How is it a Template Method step?","sellCar() is the fixed routine and createCar() is the step subclasses fill in."]],"d7":[["Static factory vs GoF Factory Method?","A static factory (List.of) cannot be overridden; the GoF one is an overridable instance method."],["How do you test with it?","Override createCar() with a fake that returns a stub product."],["When not to use it?","One fixed class, or a Map of Suppliers is enough; use Abstract Factory for matching families."]]};
QZ.p05=[
{lv:"B",q:"What problem does the Builder pattern mainly solve?",o:["Choosing which class to instantiate at run time","Creating one complex object with many (often optional) parts without long constructors or half-built objects","Sharing one instance across the whole application","Notifying many objects when something changes"],a:1,e:"Builder is about HOW one complex object is assembled. Choosing the class is Factory Method; one shared instance is Singleton; notifying is Observer."},
{lv:"B",q:"What is a telescoping constructor problem?",o:["A constructor that calls a method on a subclass","A constructor that cannot be called from outside the package","A constructor that creates objects in an infinite loop","Constructors that grow longer as options are added, with positional arguments that are easy to mix up"],a:3,e:"With telescoping constructors every new option adds another overload or another positional argument, and nothing on the call line says which true or false is which."},
{lv:"B",q:"In the dealership Builder, where do the REQUIRED values (model and fuel) go?",o:["In fluent setters called after build()","In public fields on Car","In the Car.Builder constructor, so a builder cannot be started without them","In a static variable"],a:2,e:"Required values go in the builder's constructor: new Car.Builder(\"Nexon\", \"EV\") does not compile without them. Optional values use fluent methods with defaults."},
{lv:"B",q:"What does a fluent setter such as colour(\"Red\") return, and why?",o:["void, because it only stores the value","The Car, so the chain can end","this (the builder), so calls can be chained in one readable line","A new builder copy every time"],a:2,e:"Each fluent method stores the option and returns this, so .colour(\"Red\").sunroof(true) chains on the same builder."},
{lv:"I",q:"Why is the Car constructor private, with final fields?",o:["So the builder is the only way to create a car, and the car is immutable once built","Because Java requires it for nested classes","To make the car faster to create","So the car can be subclassed by the builder"],a:0,e:"A private constructor means only Car.Builder (nested in Car) can create a Car, so every car passes through build(). Final fields make it immutable and safe to share between threads."},
{lv:"I",q:"A sunroof is not allowed on the Base trim. Where is the best place to check this rule?",o:["In the sunroof(boolean) setter","In build(), once all options are known","In the Car's toString()","In the caller, before it uses the builder"],a:1,e:"The rule spans two options (sunroof and trim). In a setter the answer would depend on the order of the calls; build() sees every option and is the single place for rules."},
{lv:"I",q:"What is the main drawback of the JavaBeans style (no-arg constructor plus setters) compared with a Builder?",o:["It needs more memory per object","It cannot set boolean fields","The object is mutable and can exist half-built, with no moment where the whole object is validated","It cannot be used with Spring"],a:2,e:"Setters leave a window where the object exists with missing values, and anyone holding it can change it later. A Builder produces the object only once, complete and validated."},
{lv:"I",q:"How do Factory Method and Builder differ?",o:["They are the same pattern with different names","Factory Method decides WHICH class to create; Builder decides HOW one complex object is assembled step by step","Builder creates families of objects; Factory Method creates one","Factory Method needs a Director; Builder does not"],a:1,e:"Factory Method picks the class (via an overridable method). Builder assembles one complex object in steps. Families of objects are Abstract Factory."},
{lv:"I",q:"Which statement about thread safety is correct?",o:["The immutable product can be shared freely, but the mutable builder should not be shared between threads","Both the builder and the product are thread-safe","Only the builder is thread-safe","Neither can be used with threads"],a:0,e:"The product has only final fields, so it is safe to share. The builder holds changing state, so use one builder per order and do not share it."},
{lv:"A",q:"In the classic GoF Builder, what does the Director do?",o:["It stores the finished product","It calls the builder's steps in a fixed order, so the same recipe can drive different ConcreteBuilders","It validates the product after build()","It replaces the Builder interface"],a:1,e:"The Director knows the order of the steps and works with the Builder interface; a CarBuilder and a PriceSheetBuilder can produce different representations from the same steps. The fluent builder usually has no Director."},
{lv:"A",q:"You need the same Car but with a different colour, and other teams share the original. Which approach fits Builder best?",o:["Add a public setColour to Car","Make the fields non-final and synchronise","Clone the car with reflection and edit the field","Add a toBuilder() that copies the fields into a builder, then colour(\"Blue\").build()"],a:3,e:"toBuilder() (copy-with) gives a new, validated immutable car and leaves the original untouched. Setters or reflection break immutability."},
{lv:"A",q:"Which statement about Lombok's @Builder is accurate?",o:["It is part of the JDK since Java 17","It makes the product thread-safe automatically","It generates the fluent builder class at compile time, but your cross-field rules still have to be written","It replaces the need for a constructor entirely at run time"],a:2,e:"Lombok is a third-party library that generates builder code from annotations. It does not know your business rules, so validation goes in a custom build or the constructor."}
];
RC.p05={d1:[["What is the problem with a constructor that takes seven positional parameters?","Unreadable and easy to swap (which boolean is which); every new option needs another constructor: the telescoping constructor problem."],["Where do required values and optional values go in a Builder?","Required in the builder's constructor; optional as fluent methods with defaults that return this."],["Which method creates the finished object and what does it do first?","build(): it validates every rule, then returns new Car(this) through the private constructor."]],
d3:[["Why not use JavaBeans setters instead?","The object is mutable and can exist half-built, with no place to validate the whole object."],["Where should a rule that involves two options live, and why?","In build(): all options are known and the order of calls does not matter."],["How does Factory Method differ from Builder?","Factory Method decides which class to create; Builder decides how one complex object is assembled."]],
d7:[["What does the GoF Director add, and when is it worth it?","It holds the order of the steps for any Builder interface; worth it when the same steps must produce different representations."],["How do you copy a built object with one change?","toBuilder() (or a with-method on a record): pre-fill a builder, change one option, call build() so the rules re-run."],["Name three real builders in the JDK or Spring.","StringBuilder, HttpRequest.newBuilder(), Stream.builder(), Locale.Builder, ProcessBuilder; Spring: ResponseEntity.ok().header().body(), UriComponentsBuilder, RestClient.builder()."]]};
QZ.p06=[
{lv:"B",q:"What does the Singleton pattern guarantee?",o:["Every object is created lazily","A class has exactly one instance, reachable through one global access point","Objects of a class can be copied cheaply","A class cannot be subclassed"],a:1,e:"<span class='qok'>Right.</span> One instance, one global way to reach it. <span class='qno'>Lazy creation, copying and final classes are separate ideas.</span>"},
{lv:"B",q:"Which three parts make a basic Java Singleton?",o:["A public constructor, a static field and a setter","An interface, an abstract class and a factory","A final field, a clone() method and a builder","A private constructor, a private static field for the instance, and a public static getInstance()"],a:3,e:"<span class='qok'>Private constructor stops outside <code>new</code>, the static field holds the one object, <code>getInstance()</code> is the doorway.</span>"},
{lv:"B",q:"In the dealership, every desk writes new VehicleRegistry(). What goes wrong?",o:["Each desk gets its own copy, so a sale at one desk is not seen by the others","The program does not compile","The registry becomes immutable","Only the first desk gets a registry"],a:0,e:"<span class='qok'>Three separate stock lists: the sales desk's copy changes, Reports still shows the car in stock.</span>"},
{lv:"B",q:"Why is the constructor of a Singleton private?",o:["So it runs faster","So the class can be serialized","So that no code outside the class can create another instance with new","So subclasses can override it"],a:2,e:"<span class='qok'>Only the class itself may call <code>new</code>, which keeps the count at one.</span>"},
{lv:"I",q:"What is eager initialisation?",o:["The instance is created when getInstance() is first called","The instance is created for every thread","The instance is created when the class is loaded, in a static final field","The instance is created by reflection"],a:2,e:"<span class='qok'>Eager = at class load. It is simple and thread-safe because the JVM loads a class once.</span> <span class='qno'>Creating on the first call is lazy.</span>"},
{lv:"I",q:"What is wrong with this lazy version when several threads call it? <code>if (instance == null) instance = new X(); return instance;</code>",o:["Two threads can both see null and each create an object","Nothing, it is always safe","It cannot compile","It makes the constructor public"],a:0,e:"<span class='qok'>The check and the creation are not one atomic step, so two threads can both pass the null check.</span>"},
{lv:"I",q:"What does the holder idiom use to be lazy and lock-free?",o:["A synchronized block","A volatile field","An enum constant","A private static nested class that is only loaded when getInstance() first uses it"],a:3,e:"<span class='qok'>Class initialisation is lazy and thread-safe, so the nested class's static field gives lazy creation with no lock in your code.</span>"},
{lv:"I",q:"How does a Spring singleton-scoped bean differ from the GoF Singleton?",o:["It is created for every request","It is one per ApplicationContext, created by the container, and the class itself could be instantiated again","It is one per JVM, enforced by a private constructor","It must be an enum"],a:1,e:"<span class='qok'>Spring's one is a container decision per <code>ApplicationContext</code>; the GoF one is enforced by the class.</span>"},
{lv:"I",q:"Why is a Singleton hard to unit-test, and what is the usual fix?",o:["It is a hidden global dependency whose state leaks between tests; depend on an interface and inject it","It is slow; make it lazy","It cannot be created in tests; make the constructor public","It is not serializable; add readResolve()"],a:0,e:"<span class='qok'>Callers use <code>getInstance()</code> inside, so a fake cannot be passed in. Constructor injection of an interface fixes that.</span>"},
{lv:"A",q:"Why must the instance field be volatile in double-checked locking?",o:["To make the field final","To stop the JVM from garbage-collecting it","Because creating the object is several steps that may be reordered, so another thread could see a non-null but half-built object","Because synchronized only works on volatile fields"],a:2,e:"<span class='qok'>Allocate, run the constructor and assign the reference can be reordered; <code>volatile</code> forbids that and gives visibility.</span>"},
{lv:"A",q:"setAccessible(true) on the private constructor of a class-based Singleton and then newInstance(). What happens, and what resists it?",o:["It throws always; nothing is needed","The existing instance is returned","The JVM shuts down","A second instance is created; an enum singleton resists it (reflection cannot create enum objects)"],a:3,e:"<span class='qok'>It switches off the private check, so a second object appears. An enum throws <code>IllegalArgumentException</code>: Cannot reflectively create enum objects.</span>"},
{lv:"A",q:"A Serializable Singleton is written to bytes and read back. What gives you the same instance again?",o:["Marking the field transient","A readResolve() method that returns the instance (or using an enum)","Making the constructor public","Nothing: deserialization always returns the original"],a:1,e:"<span class='qok'>Deserialization builds a new object unless <code>readResolve()</code> hands back the real one; enums are handled by the JVM.</span>"}
];
RC.p06={"d1":[["What are the three parts of a basic Java Singleton?","Private constructor, private static field holding the instance, public static getInstance()."],["What goes wrong when each desk writes new VehicleRegistry()?","Each gets its own copy; a sale at one desk is not seen by the others, so the copies disagree."],["Eager or lazy initialisation: what is the difference?","Eager creates the object at class load (simple, thread-safe); lazy creates it on the first getInstance() call (needs thread care)."]],"d3":[["Name four thread-safe ways to make a Singleton.","Eager static final, synchronized getInstance(), double-checked locking with volatile, holder idiom, or an enum."],["Why is volatile needed in double-checked locking?","Construction and publishing the reference can be reordered, so another thread might see a half-built object."],["Singleton vs a static utility class?","A Singleton is a real object (interface, state, lazy); a static class has no object and cannot be replaced or mocked easily."]],"d7":[["How can reflection, serialization and cloning break a Singleton, and how does an enum resist?","setAccessible on the private constructor, deserialization creating a new object (fix readResolve), Cloneable clone(); an enum is created once by the JVM and blocks all three."],["Singleton vs Spring singleton scope?","Spring's is one per ApplicationContext, container-managed and injectable; the GoF one is enforced by the class, about one per class loader."],["Why is Singleton hard to test, and what is the fix?","Hidden global state and a hard-wired getInstance(); depend on an interface and inject it."]]};
QZ.p07=[{"lv":"B","q":"What does the Prototype pattern do?","o":["It makes sure a class has only one instance","It creates a new object by copying an existing, configured one","It builds an object step by step from parts","It lets a subclass decide which class to create"],"a":1,"e":"<span class='qok'>Right.</span> Start from a finished example and copy it. <span class='qno'>One instance is Singleton, step by step is Builder, subclass decides is Factory Method.</span>"},
{"lv":"B","q":"A demo car holds a List of accessories. You make a SHALLOW copy and add an accessory to the copy. What happens to the original?","o":["Nothing, the original is unchanged","The program throws an exception","The original is deleted","It also gets the accessory, because both share the same list"],"a":3,"e":"<span class='qok'>A shallow copy copies the reference to the list, not the list.</span> Both cars point at one list, so the change shows in both."},
{"lv":"B","q":"What is a deep copy?","o":["A copy that also copies the mutable objects inside, so the two share nothing mutable","A copy made with Object.clone()","A copy stored in a database","A copy that is made only once"],"a":0,"e":"<span class='qok'>A deep copy copies the inner objects too.</span> Immutable values such as String may still be shared safely."},
{"lv":"B","q":"Why declare copy() on the Car interface?","o":["So the compiler can inline it","So that Car can be serialized","So the caller can copy a car without knowing whether it is a PetrolCar or an EvCar","So that cars cannot be changed"],"a":2,"e":"<span class='qok'>Each class copies itself,</span> so the caller depends only on the interface and needs no instanceof chain."},
{"lv":"I","q":"What should CarRegistry.create(\"nexon-demo\") return?","o":["The stored template itself, to save memory","A new PetrolCar built with new in the registry","A copy of the stored template","null if the template was already used"],"a":2,"e":"<span class='qok'>Return template.copy().</span> <span class='qno'>If the template itself is handed out, one client can change the master and every later copy inherits it.</span>"},
{"lv":"I","q":"Which is a problem with Object.clone() and Cloneable (Effective Java, Item 13)?","o":["clone() always makes a deep copy, which is slow","clone() calls the constructor twice","Cloneable declares the clone() method, so it cannot be overridden","It is shallow by default and does not call a constructor"],"a":3,"e":"<span class='qok'>clone() copies fields as they are (shallow) and runs no constructor.</span> It also throws a checked exception and fights final fields. Prefer a copy constructor."},
{"lv":"I","q":"What does ArrayList.clone() give you?","o":["A shallow copy: a new list holding the same element objects","A deep copy of every element","The same list object","An unmodifiable list"],"a":0,"e":"<span class='qok'>It is shallow.</span> Changing a mutable element through one list is visible through the other. <code>new ArrayList&lt;&gt;(list)</code> behaves the same way."},
{"lv":"I","q":"How is Spring's @Scope(\"prototype\") related to the Prototype pattern?","o":["It clones an existing bean instance","It makes a bean a Singleton","It creates a new bean from the bean definition each time it is requested; it does not clone an instance","It copies the bean into the next request"],"a":2,"e":"<span class='qok'>Conceptually similar only.</span> You get a fresh object each time, but it is built from the definition, not copied."},
{"lv":"I","q":"What is the main difference between Prototype and Memento?","o":["Prototype is for Spring, Memento is for the JDK","Memento creates objects by calling constructors","Prototype makes a new object to use; Memento saves a snapshot to restore later (undo)","There is no difference"],"a":2,"e":"<span class='qok'>Both copy state, for different goals.</span> A memento is kept and put back; a prototype copy lives on as its own object."},
{"lv":"I","q":"For an immutable record CarSpec, how do you get a red version of a blue one?","o":["Call setColour on the record","Call clone() on the record","Make the record Cloneable","Use a withColour method that returns a new CarSpec"],"a":3,"e":"<span class='qok'>Records are immutable, so you create a new one: <code>nexon.withColour(\"Red\")</code>.</span> No clone or setter is needed, and sharing the unchanged parts is safe."},
{"lv":"A","q":"A deep-copy method calls copy() on every field. The objects point at each other in a cycle (a Car holds its Dealer, the Dealer holds its Cars). What happens, and what is the fix?","o":["It recurses forever (StackOverflowError); keep an IdentityHashMap of original to copy and reuse existing copies","Nothing special: the JVM detects the cycle","A CloneNotSupportedException is thrown","The copy is shallow instead"],"a":0,"e":"<span class='qok'>A naive deep copy never ends on a cycle.</span> Remember what you already copied (an identity map from original to copy), or avoid copying such a graph."},
{"lv":"A","q":"Why can a final field be a problem when you implement clone() with super.clone()?","o":["final fields are not copied at all","final fields make clone() return null","super.clone() copies them as they are, and you cannot assign a final field again to give the copy its own list","The compiler forbids Cloneable on classes with final fields"],"a":2,"e":"<span class='qok'>The copy shares the same list, and a final field cannot be re-assigned inside clone().</span> A copy constructor can assign its own new list to a final field."}];
RC.p07={"d1":[["What does Prototype do, in one sentence?","It creates a new object by copying an existing, configured example, then changing what differs."],["What does a shallow copy share with the original?","The references to inner objects, such as the accessories list and the service history."],["Why does a registry return template.copy()?","So clients never change the master template."]],"d3":[["How do you make a deep copy of a car with a list, a map and a ServiceHistory?","In a copy constructor: new list with addAll, new map with putAll, history.copy()."],["Name three problems with Object.clone().","Shallow by default, no constructor call, checked CloneNotSupportedException (also final fields)."],["Which Java collection copy is shallow?","ArrayList.clone() and new ArrayList<>(collection): new list, same elements."]],"d7":[["Prototype vs Builder?","Builder assembles an object from parts; Prototype copies a finished example."],["Prototype vs Memento?","Prototype makes a new object to use; Memento is a snapshot to restore later."],["Is Spring prototype scope the pattern?","Conceptually similar: a new bean from the definition per request, not a clone of an instance."]]};
QZ.p08=[
{lv:"B",q:"What does an Abstract Factory create?",o:["Exactly one object, chosen by a subclass","A family of related objects that must match","One complex object built step by step","A copy of an existing object"],a:1,e:"An Abstract Factory has one create method per product and one implementation per family, so the products it hands out belong together."},
{lv:"B",q:"In the dealership code, which type plays the AbstractFactory role?",o:["AssemblyLine","Engine","PartsFactory","EuPlate"],a:2,e:"PartsFactory is the interface with createEngine(), createHeadlights() and createPlate(). AssemblyLine is the client."},
{lv:"B",q:"Why can an EU car not get an Indian plate when AssemblyLine receives an EuPartsFactory?",o:["The plate class checks the market name","The compiler rejects Indian plates","Java forbids two plate classes","Every part comes from the same factory, so all parts belong to the EU family"],a:3,e:"The client holds one factory and asks only it for parts. EuPartsFactory creates only EU parts."},
{lv:"B",q:"What was the bug in the naive code?",o:["The plate ladder tested \"EUR\" instead of \"EU\", so EU cars fell into the else branch","The engine was too expensive","Headlights were created twice","The factory returned null"],a:0,e:"Three separate if / else ladders can disagree. A typo in one gave EU cars an Indian plate with no error."},
{lv:"I",q:"What is the relationship between Abstract Factory and Factory Method?",o:["They are the same pattern","Each create method of an Abstract Factory is itself a Factory Method","Abstract Factory forbids factory methods","Factory Method creates families, Abstract Factory creates one object"],a:1,e:"A Factory Method creates one product. An Abstract Factory is a group of such methods that must be used together."},
{lv:"I",q:"The dealership opens in the US. What is the change with Abstract Factory?",o:["Edit every create method of the other factories","Add a branch to AssemblyLine","Add UsPartsFactory (and the US products); existing classes are not edited","Change the PartsFactory interface"],a:2,e:"A new family is one new factory class plus its products. That is the easy direction."},
{lv:"I",q:"The dealership adds a Battery product for every market. What happens?",o:["Nothing, factories pick it up automatically","The PartsFactory interface and every concrete factory must change","Only AssemblyLine changes","Only the new Battery class changes"],a:1,e:"A new product kind adds a method to the interface, so every implementation must add it. That is the pattern's weakness."},
{lv:"I",q:"How does the client get its factory in the refactored code?",o:["By calling a static getInstance()","By reading the market text in each method","By creating it with new inside assemble()","Through its constructor (constructor injection)"],a:3,e:"AssemblyLine(PartsFactory parts) stores the factory it is given, so the choice of family is made outside the client."},
{lv:"I",q:"When is plain Abstract Factory the wrong choice?",o:["When there is a single product, or product kinds keep growing","When families must match","When you want to fake parts in tests","When a new market arrives"],a:0,e:"One product needs only a Factory Method or a plain factory, and growing product kinds edit every factory."},
{lv:"I",q:"How can Spring replace a manual \"which factory?\" if / else?",o:["A @Profile on a @Configuration class registers the family's beans only when that profile is active","@Autowired creates the market name","Spring rewrites the constructor","It cannot: the if / else is required"],a:0,e:"The active profile chooses the family once at startup, and services just receive the injected beans."},
{lv:"A",q:"A teammate gives createBattery() a default method returning an Indian battery for all markets. What is the risk?",o:["Interfaces cannot have default methods","It runs slower","The EU factory silently inherits an Indian battery: a mismatched family the compiler does not report","Nothing, it is the recommended practice"],a:2,e:"The pattern exists to prevent mismatches. A default hides the missing override instead of making the compiler list it."},
{lv:"A",q:"Which modern Java option fits a family that is only \"which class for each product\"?",o:["A record of Suppliers (or an enum implementing the factory)","A static switch in every method","Reflection on class names","A synchronized singleton per product"],a:0,e:"A record holding Suppliers, or an enum with one constant per market, gives a whole family without a class per market."}
];
RC.p08={d1:[["What does an Abstract Factory create, and what does it guarantee?","A family of related products via one create method per product; the client gets one factory, so the products always match."],["Name the roles in the dealership example.","AbstractFactory PartsFactory, ConcreteFactories IndiaPartsFactory / EuPartsFactory, AbstractProducts Engine / Headlights / NumberPlate, Client AssemblyLine."],["What was the naive bug?","Separate if / else ladders disagreed: the plate ladder never matched, so an EU car got an Indian plate."]],
d3:[["What is easy and what is hard to add?","Easy: a new family (one new factory class). Hard: a new product kind (the interface and every factory change)."],["How is each create method related to Factory Method?","Each one is a Factory Method: it creates one product and returns its interface."],["How does Spring help choose the factory?","A @Profile on a @Configuration class registers one family's beans; DI injects them, so no code reads the market."]],
d7:[["When would you avoid Abstract Factory?","For a single product, or when product kinds keep growing so every factory changes each time."],["Give two modern Java ways to write a factory.","A record of Suppliers, or an enum that implements the factory interface."],["How do you test code that uses it?","Pass a fake factory that returns stub products; the client only knows the interfaces."]]};
